17.3 색 배열(color scheme)

17.3.1 함수

snu.color.scheme.generator &lt;- function(sel, type){
  if (type == "seq"){
    col.schemes &lt;- c("brewer.yl_gn", "brewer.yl_gn_bu", "brewer.gn_bu", "brewer.bu_gn", "brewer.pu_bu_gn", "brewer.pu_bu", "brewer.bu_pu", "brewer.rd_pu", "brewer.pu_rd", "brewer.or_rd", "brewer.yl_or_rd", "brewer.yl_or_br", "brewer.purples", "brewer.blues", "brewer.greens", "brewer.oranges", "brewer.reds", "brewer.greys")
  }
  else if(type == "div"){
    col.schemes &lt;- c("brewer._puor", "brewer.br_bG", "brewer.pr_gn", "brewer.pi_yg", "brewer.rd_bu", "brewer.rd_gy", "brewer.rd_yl_bu", "brewer.spectral", "brewer.rd_ylgn")
  }
  else {col.schemes = c("brewer.set3", "brewer.pastel1", "brewer.set1", "brewer.pastel2", "brewer.set2", "brewer.dark2", "brewer.paired", "brewer.accent")}
  col.sel &lt;- col.schemes[sel]
  n &lt;- length(sel)
  map.name.list &lt;- list()
  i &lt;- 1
  for (i in 1:n){
    my.pal &lt;- col.sel[i]
    var.sel &lt;- "House1_p"
    map.name &lt;- paste0(my.pal, ".map")
    map.name &lt;- tm_shape(seoul_df) + 
      tm_polygons(
        fill = var.sel, 
        fill.scale = tm_scale_intervals(
          values = my.pal,
          breaks = c(-Inf, 15, 25, 35, 45, 55, 65, Inf),
        ),
        fill.legend = tm_legend_hide()
      ) +
      tm_shape(seoul_gu) + tm_borders(lwd = 1.5, col = "black") +
      tm_layout(inner.margins = c(0.05, 0.05, 0.05, 0.05)) +
      tm_credits(text = my.pal, size = 1, position = c(0.05, 0.75))
      map.name.list[[i]] &lt;- map.name
  }
  map.name.list
}


snu.color.scheme.generator &lt;- function(sel, type){
  if (type == "seq"){
    col.schemes &lt;- c("YlGn", "YlGnBu", "GnBu", "BuGn", "PuBuGn", "PuBu", "BuPu", "RdPu", "PuRd", 
                     "OrRd", "YlOrRd", "YlOrBr", "Purples", "Blues", "Greens", "Oranges", "Reds", "Greys")
  }
  else if(type == "div"){
    col.schemes &lt;- c("PuOr", "BrBG", "PRGn", "PiYG", "RdBu", "RdGy", "RdYlBu", "Spectral", "RdYlGn")
  }
  else {col.schemes = c("Set3", "Pastel1", "Set1", "Pastel2", "Set2", "Dark2", "Paired", "Accent")}
  col.sel &lt;- col.schemes[sel]
  n &lt;- length(sel)
  map.name.list &lt;- list()
  for (i in 1:n){
    my.pal &lt;- col.sel[i]
    var.sel &lt;- "House1_p"
    map.name &lt;- paste0(my.pal, ".map")
    if (type == "seq" | type == "div"){
       map.name &lt;- tm_shape(seoul_df) + 
      tm_polygons(
        fill = var.sel, 
        fill.scale = tm_scale_intervals(
          values = my.pal,
          breaks = c(-Inf, 15, 25, 35, 45, 55, 65, Inf),
        ),
        fill.legend = tm_legend_hide()
      ) +
      tm_shape(seoul_gu) + tm_borders(lwd = 1.5, col = "black") +
      tm_credits(text = my.pal, size = 1, position = c(0.05, 0.95))
      map.name.list[[i]] &lt;- map.name
    }
    else{
      map.name &lt;- tm_shape(seoul_df) +
        tm_polygons(
          fill = "MAP_COLORS",
          fill.scale = tm_scale_categorical(
            values = my.pal
          )
        ) +
        tm_shape(seoul_gu) + tm_borders(lwd = 1.5, col = "black") +
        tm_credits(text = my.pal, size = 1, position = c(0.05, 0.95))
      map.name.list[[i]] &lt;- map.name
    }
  }
  map.name.list
}


